import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.junit.Assert.*;

@RunWith(JUnit4.class)
public class CommandLine_hasOption_TriageGen0Test {

    @Test
    public void testHasOption_String_NullOpt_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {});
        assertFalse(line.hasOption(null));
    }

    @Test
    public void testHasOption_String_EmptyOpt_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {});
        assertFalse(line.hasOption(""));
    }

    @Test
    public void testHasOption_String_NullOptions_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {});
        assertFalse(line.hasOption("opt"));
    }

    @Test
    public void testHasOption_String_ExistingOption_ReturnsTrue() {
        CommandLine line = new CommandLine(new String[] {"-opt", "--opt"});
        assertTrue(line.hasOption("opt"));
    }

    @Test
    public void testHasOption_String_NonExistingOption_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {"-opt", "--opt"});
        assertFalse(line.hasOption("nonOpt"));
    }

    @Test
    public void testHasOption_String_SingleDashOption_ReturnsTrue() {
        CommandLine line = new CommandLine(new String[] {"-opt"});
        assertTrue(line.hasOption("opt"));
    }

    @Test
    public void testHasOption_String_DoubleDashOption_ReturnsTrue() {
        CommandLine line = new CommandLine(new String[] {"--opt"});
        assertTrue(line.hasOption("opt"));
    }

    @Test
    public void testHasOption_String_SingleDashOptionWithValue_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {"-opt=opt"});
        assertFalse(line.hasOption("opt"));
    }

    @Test
    public void testHasOption_String_DoubleDashOptionWithValue_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {"--opt=opt"});
        assertFalse(line.hasOption("opt"));
    }

    @Test
    public void testHasOption_String_SingleDashOptionWithArg_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {"-opt arg"});
        assertFalse(line.hasOption("opt"));
    }

    @Test
    public void testHasOption_String_DoubleDashOptionWithArg_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {"--opt arg"});
        assertFalse(line.hasOption("opt"));
    }

    @Test
    public void testHasOption_Char_NullOpt_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {});
        assertFalse(line.hasOption((char) 0));
    }

    @Test
    public void testHasOption_Char_EmptyOpt_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {});
        assertFalse(line.hasOption(''));
    }

    @Test
    public void testHasOption_Char_NullOptions_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {});
        assertFalse(line.hasOption('a'));
    }

    @Test
    public void testHasOption_Char_ExistingOption_ReturnsTrue() {
        CommandLine line = new CommandLine(new String[] {"-a", "--a"});
        assertTrue(line.hasOption('a'));
    }

    @Test
    public void testHasOption_Char_NonExistingOption_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {"-a", "--a"});
        assertFalse(line.hasOption('b'));
    }

    @Test
    public void testHasOption_Char_SingleDashOption_ReturnsTrue() {
        CommandLine line = new CommandLine(new String[] {"-a"});
        assertTrue(line.hasOption('a'));
    }

    @Test
    public void testHasOption_Char_DoubleDashOption_ReturnsTrue() {
        CommandLine line = new CommandLine(new String[] {"--a"});
        assertTrue(line.hasOption('a'));
    }

    @Test
    public void testHasOption_Char_SingleDashOptionWithValue_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {"-a=opt"});
        assertFalse(line.hasOption('a'));
    }

    @Test
    public void testHasOption_Char_DoubleDashOptionWithValue_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {"--a=opt"});
        assertFalse(line.hasOption('a'));
    }

    @Test
    public void testHasOption_Char_SingleDashOptionWithArg_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {"-a arg"});
        assertFalse(line.hasOption('a'));
    }

    @Test
    public void testHasOption_Char_DoubleDashOptionWithArg_ReturnsFalse() {
        CommandLine line = new CommandLine(new String[] {"--a arg"});
        assertFalse(line.hasOption('a'));
    }
}
